import{_ as o,o as r,c as n,a3 as s,j as e,a as i}from"./chunks/framework.z_KJ15Ep.js";const a="/bilder/import-export-statistik/export-fotoliste-1-auswahl.png",l="/bilder/import-export-statistik/export-fotoliste-2-fertig.png",p="/bilder/import-export-statistik/export-fotoliste-3-fotoliste.png",k=JSON.parse('{"title":"Eine Fotoliste exportieren","description":"","frontmatter":{"title":"Eine Fotoliste exportieren","source_pageid":891,"source_revision":5280},"headers":[],"relativePath":"schild3/import-export-statistik/fotoliste-verwaltung-export.md","filePath":"schild3/import-export-statistik/fotoliste-verwaltung-export.md"}'),d={name:"schild3/import-export-statistik/fotoliste-verwaltung-export.md"};function m(u,t,c,g,h,f){return r(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="eine-fotoliste-exportieren" tabindex="-1">Eine Fotoliste exportieren <a class="header-anchor" href="#eine-fotoliste-exportieren" aria-label="Permalink to &quot;Eine Fotoliste exportieren&quot;">​</a></h1><p>Erstellen Sie eine Fotoliste mit Datenbank-ID und den zugehörigen Schülerangaben, damit Fotos später zugeordnet werden können.</p><p><a href="/bilder/import-export-statistik/export-fotoliste-1-auswahl.png"><img src="'+a+'" alt="Anstoßen des Exports und Wahl der Verzeichnisses." loading="lazy"></a></p><p><em>Anstoßen des Exports und Wahl der Verzeichnisses.</em></p><p>Nach dem Aufruf des Menüpunktes &quot;<em>Verwaltung ➜ Export ➜ Fotoliste&quot;</em> werden Sie gebeten, einen Zielordner auszuwählen.</p><p>Dort wird eine Datei mit dem Namen <em>Fotoliste.txt</em> gespeichert.</p><p><a href="/bilder/import-export-statistik/export-fotoliste-2-fertig.png"><img src="'+l+'" alt="Meldung des abgeschlossenen Exports." loading="lazy"></a></p><p><em>Meldung des abgeschlossenen Exports.</em></p><p><a href="/bilder/import-export-statistik/export-fotoliste-3-fotoliste.png"><img src="'+p+'" alt="Die Fotoliste in einer Textdatei: SchILD-ID, Name, Vorname, Geburtsdatum und Klasse." loading="lazy"></a></p><p><em>Die Fotoliste in einer Textdatei: SchILD-ID, Name, Vorname, Geburtsdatum und Klasse.</em></p><p><strong>Inhalt der Fotoliste</strong></p><p>Die Schüler bekommen beim Export ihre <em>interne Datenbank-ID</em> und können daran identifiziert werden. Weiterhin werden <em>Name, Vorname, Geburtsdatum</em> und die <em>Klasse</em> ausgegeben.</p><p>Diese Liste wurde häufig bei Schulfotografen genutzt, damit die Fotos später wieder zum Schüler zugeordnet werden konnten.</p>',13),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),i("Hinweis")]),e("p",null,"Für den automatischen Foto-Import gibt es ein kostenpflichtiges Programm der Firma Ribeka.")],-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Fotoliste_(Verwaltung_Export)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),i(" · Quellrevision 5280.")],-1)])])}const _=o(d,[["render",m]]);export{k as __pageData,_ as default};
